import React from 'react';

const TeacherSidebar = ({ activeItem, setActiveItem, onLogout }) => {
  const menuSections = [
    {
      title: '📋 Mis Cursos',
      items: [
        { id: 'my-courses', label: 'Ver lista de cursos asignados' },
        { id: 'course-students', label: 'Ver estudiantes por curso' },
        { id: 'attendance', label: 'Llamar lista de asistencia' },
        { id: 'student-notes', label: 'Registrar observaciones' }
      ]
    },
    {
      title: '✅ Evaluaciones',
      items: [
        { id: 'upload-grades', label: 'Subir notas de evaluaciones' },
        { id: 'grade-activities', label: 'Calificar tareas o actividades' },
        { id: 'recovery', label: 'Registrar recuperaciones' },
        { id: 'course-average', label: 'Ver promedio general por curso' }
      ]
    },
    {
      title: '📝 Tareas',
      items: [
        { id: 'assign-tasks', label: 'Asignar nuevas tareas' },
        { id: 'submitted-tasks', label: 'Ver tareas entregadas' },
        { id: 'task-history', label: 'Ver historial de entregas' }
      ]
    },
    {
      title: '🧾 Permisos',
      items: [
        { id: 'view-permissions', label: 'Consultar permisos registrados' },
        { id: 'justified-absences', label: 'Ver estudiantes con faltas justificadas' },
        { id: 'filter-permissions', label: 'Filtrar por fecha o curso' }
      ]
    }
  ];

  return (
    <div className="w-64 bg-white/10 backdrop-blur-md text-white h-screen fixed left-0 top-0 pt-16 overflow-y-auto shadow-lg border-r border-white/20">
      <div className="p-4">
        <h2 className="text-xl font-bold mb-6 px-2 flex items-center gap-2 text-blue-400">
          <span>👨‍🏫</span>
          <span>Panel Docente</span>
        </h2>

        <div className="space-y-6">
          {menuSections.map((section) => (
            <div key={section.title} className="space-y-1">
              <h3 className="text-xs font-bold text-gray-300 uppercase tracking-wider mb-1 px-2 flex items-center gap-2">
                <span>{section.title.split(' ')[0]}</span>
                <span className="flex-1">{section.title.split(' ').slice(1).join(' ')}</span>
              </h3>
              <ul className="space-y-1">
                {section.items.map((item) => (
                  <li key={item.id}>
                    <button
                      onClick={() => setActiveItem(item.id)}
                      className={`w-full text-left px-4 py-2 rounded-lg transition text-sm flex items-center gap-2 ${
                        activeItem === item.id
                          ? 'bg-blue-600/90 text-white shadow-inner'
                          : 'hover:bg-white/10 hover:text-white text-gray-300'
                      }`}
                    >
                      <span>{item.label}</span>
                    </button>
                  </li>
                ))}
              </ul>
            </div>
          ))}
        </div>

        <div className="mt-8 pt-4 border-t border-white/20">
          <button
            onClick={onLogout}
            className="w-full text-left px-4 py-2 rounded-lg transition text-sm text-red-400 hover:bg-white/10 hover:text-red-300 flex items-center gap-2"
          >
            <span>🔒</span>
            <span>Cerrar Sesión</span>
          </button>
        </div>
      </div>
    </div>
  );
};

export default TeacherSidebar;
